import sys


def calc(expr: str) -> int | str:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ZeroDivisionError
        sign = 1 if (a < 0) == (b < 0) else -1
        return sign * (abs(a) // abs(b))

    def parse_expr() -> int:
        left = parse_term()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return left
            op = s[i]
            i += 1
            right = parse_term()
            left = left + right if op == "+" else left - right

    def parse_term() -> int:
        left = parse_unary()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return left
            op = s[i]
            i += 1
            right = parse_unary()
            if op == "*":
                left = left * right
            else:
                q = trunc_div(left, right)
                left = q if op == "/" else left - right * q

    def parse_unary() -> int:
        skip()
        if i < n and s[i] == "-":
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> int:
        left = parse_primary()
        skip()
        if i < n and s[i] == "^":
            i += 1
            right = parse_unary()
            if right < 0:
                raise ValueError
            left = left ** right
        return left

    def parse_primary() -> int:
        skip()
        if s[i] == "(":
            i += 1
            val = parse_expr()
            skip()
            i += 1
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
